    # Test 1: Basit bir örnek
    deps1 = {
        "b": ["a"],
        "c": ["a"],
        "a": []
    }
    print("Test 1:", kurulum_sirasi(deps1))

    # Test 2: Döngü
    deps2 = {
        "a": ["b"],
        "b": ["c"],
        "c": ["a"]
    }
    try:
        kurulum_sirasi(deps2)
    except DonguHatasi as e:
        print("Test 2 - DonguHatasi:", e.dongu)

